export type ScopeFlag = 'core' | 'internal' | 'conditional';
export type DepthBand = 'hire-ready' | 'adequate-with-gaps' | 'exceeds-coverage';
export type DecompositionVerdict = 'split_at_scale' | 'merge_candidate' | 'keep_combined';

export interface RoleMatrixEntry {
  id: string;
  name: string;
  function: string;
  /** Curated coverage heuristic (0-100). See ROLE_MATRIX_META.depthFormula. */
  depthScore: number;
  depthBand: DepthBand;
  resourceCount: number;
  /** Resources that returned HTTP 404 in the 2026-11-20 link check. */
  staleCount: number;
  scopeCounts: Record<ScopeFlag, number>;
  skillPacks: string[];
  gapsCount: number;
  verdict: DecompositionVerdict;
  hasScience: boolean;
}

export interface CandidateResource {
  name: string;
  domain: string;
  type: string;
  url: string;
  flag: ScopeFlag;
  level: string;
  prerequisite: string;
  access: string;
  evidence: 'E3' | 'E2' | 'E1';
  trigger?: string;
}

export interface CandidateEvaluationTask {
  taskId: string;
  taskType: string;
  task: string;
  evidenceRequired: string;
}

export interface ProposedRole {
  id: string;
  name: string;
  status: string;
  justification: string;
  recommendedForm: string;
  splitTriggers: string[];
  ownedConditionalCapabilities: string[];
  charter: {
    function: string;
    mission: string;
    outputs: string;
    skills: string;
    senior: string;
    interfaces: string;
  };
  /** Agent-charter delegation contexts sharing this candidate's territory. */
  agentContexts: string[];
  agentInstantiation: string;
  /**
   * Fuller specialist inventory attached to the CANDIDATE DRAFT ONLY (from
   * ui_ux_role_resources.json proposed_role.resources, alias-canonicalized).
   * Never a standing role; never contributes to any depth score.
   */
  inventory: Record<'foundational' | 'core' | 'advanced', CandidateResource[]>;
  /** ET-CAND-* evaluation tasks (draft battery from the three UI/UX charters). */
  evaluationTasks: CandidateEvaluationTask[];
}

